CREATE DATABASE supply_chain_db;
USE supply_chain_db;


-- Date range: 2024-01-01 to 2025-12-31. 
DROP TABLE IF EXISTS returns; DROP TABLE IF EXISTS shipments; DROP TABLE IF EXISTS order_items; DROP TABLE IF EXISTS sales_orders;
DROP TABLE IF EXISTS po_items; DROP TABLE IF EXISTS purchase_orders; DROP TABLE IF EXISTS inventory; DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS employees; DROP TABLE IF EXISTS customers; DROP TABLE IF EXISTS carriers; DROP TABLE IF EXISTS warehouses; DROP TABLE IF EXISTS suppliers;

CREATE TABLE suppliers (supplier_id INT PRIMARY KEY, supplier_name VARCHAR(80), country VARCHAR(40), rating DECIMAL(3,1), payment_terms_days INT, onboarded_date DATE);
CREATE TABLE warehouses (warehouse_id INT PRIMARY KEY, warehouse_name VARCHAR(60), city VARCHAR(40), region VARCHAR(20), capacity_units INT);
CREATE TABLE carriers (carrier_id INT PRIMARY KEY, carrier_name VARCHAR(60), mode VARCHAR(20));
CREATE TABLE employees (employee_id INT PRIMARY KEY, full_name VARCHAR(60), job_role VARCHAR(40), manager_id INT, warehouse_id INT, hire_date DATE, salary INT);
CREATE TABLE customers (customer_id INT PRIMARY KEY, customer_name VARCHAR(80), email VARCHAR(100), segment VARCHAR(20), city VARCHAR(40), region VARCHAR(20), signup_date DATE);
CREATE TABLE products (product_id INT PRIMARY KEY, product_name VARCHAR(80), category VARCHAR(30), supplier_id INT, unit_cost DECIMAL(10,2), unit_price DECIMAL(10,2), reorder_level INT, FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id));
CREATE TABLE inventory (warehouse_id INT, product_id INT, quantity_on_hand INT, last_updated DATE, PRIMARY KEY (warehouse_id, product_id));
CREATE TABLE purchase_orders (po_id INT PRIMARY KEY, supplier_id INT, warehouse_id INT, order_date DATE, expected_date DATE, received_date DATE, status VARCHAR(20));
CREATE TABLE po_items (po_item_id INT PRIMARY KEY, po_id INT, product_id INT, quantity_ordered INT, quantity_received INT, unit_cost DECIMAL(10,2));
CREATE TABLE sales_orders (order_id INT PRIMARY KEY, customer_id INT, warehouse_id INT, order_date DATE, status VARCHAR(20));
CREATE TABLE order_items (order_item_id INT PRIMARY KEY, order_id INT, product_id INT, quantity INT, unit_price DECIMAL(10,2), discount_pct DECIMAL(4,2));
CREATE TABLE shipments (shipment_id INT PRIMARY KEY, order_id INT, carrier_id INT, ship_date DATE, promised_date DATE, delivery_date DATE, shipping_cost DECIMAL(10,2), status VARCHAR(20));
CREATE TABLE returns (return_id INT PRIMARY KEY, order_item_id INT, return_date DATE, quantity INT, reason VARCHAR(40));

